export function playSummaryReveal(): void {
  const context = audioContext;
  if (!context) return;
  const now = context.currentTime + 0.01;
  playSample('stamp', { at: now, gain: 0.82 });
  playSample('sting_relief', { at: now + 0.38, gain: 0.68 });
}
